#!/bin/sh
# tools/check.sh - the verify step. Exit 0 = everything below passed. Later slices extend it.
#   1. generator runs on the harness's fake azalea (rustdoc JSON, harness/fake/rustdoc)
#   2. generated files are byte-identical to the golden sha1 list (tools/golden.sh compare; ALLOWED_DIFF.md for exceptions)
#   3. tools/rdj_selftest.py: the rustdoc JSON loader + types/defs/methods/paths front end pieces (tools/rdj.py, rdj_index.py)
#      against the committed fixture; also fails when the
#      fixture is stale (harness/fake/azalea changed without re-running tools/make_rustdoc_json.sh)
#   3b. the generator on harness/fake into a scratch dir equals the golden
#   3e. coverage ledger (tools/coverage.py: selftest, then every API GEN_REPORT.json lists as not generated is classified in
#       tools/coverage.toml; `--strict`, run by hand, is the finish line of the full-coverage chain: no `todo` left)
#   4. nothing in tools/baseline_api.txt vanished from types/bindings.d.luau (when a build produced it)
#   5. hand-written glue in harness/src/luau matches the real rust_binds/luau (real_*.rs, cargo feature `real`: only declared in mod.rs, never in the harness)
#   6. harness builds (no `error`) and test.luau runs without a `[luau]` error line
#   7. bind e2e (tools/bind_e2e.sh): the bind_gen register() for rust/ compiled into a scratch harness, tests/e2e/bind_demo.luau run through it
# Env: SKIP_HARNESS=1 (log A: no toolchain; also implied when `cargo` is not on PATH).
set -u
PYTHONDONTWRITEBYTECODE=1; export PYTHONDONTWRITEBYTECODE
cd "$(dirname "$0")/.." || exit 2
[ -d /usr/lib/rust-1.91/bin ] && PATH=/usr/lib/rust-1.91/bin:$PATH
. tools/env.sh
fail=0
bad() { echo "FAIL: $*"; fail=1; }

echo "== generator (harness/fake)"
python3 tools/zenpel_gen.py --azalea harness/fake --rustdoc harness/fake/rustdoc --rust-out harness/src/luau --luau-out harness/luau \
    || bad "generator failed on harness/fake"

echo "== golden (generated files vs tools/golden/fake.sha1)"
sh tools/golden.sh compare || bad "generated files differ from tools/golden (see above)"

echo "== generator (harness/fake into a scratch dir) vs the golden"
rm -rf /tmp/azl-rdj-out && mkdir -p /tmp/azl-rdj-out/rust /tmp/azl-rdj-out/luau
cp harness/src/luau/extra_*.rs /tmp/azl-rdj-out/rust/ 2>/dev/null
python3 tools/zenpel_gen.py --azalea harness/fake --rustdoc harness/fake/rustdoc \
    --rust-out /tmp/azl-rdj-out/rust --luau-out /tmp/azl-rdj-out/luau || bad "generator failed on harness/fake (scratch dir)"
sh tools/golden.sh compare fake /tmp/azl-rdj-out/rust /tmp/azl-rdj-out/luau || bad "generator output differs from the golden"

echo "== rustdoc JSON loader selftest (fixture harness/fake/rustdoc)"
python3 tools/rdj_selftest.py || bad "tools/rdj_selftest.py failed"
echo "== fuzz regressions (tools/fuzz/regress.py: bugs found by the messy-source cases stay fixed)"
python3 tools/fuzz/regress.py || bad "tools/fuzz/regress.py failed"

echo "== type mapper selftest (tools/mapper_selftest.py: containers)"
python3 tools/mapper_selftest.py || bad "tools/mapper_selftest.py failed"

echo "== bindgen selftest (tools/bindgen_selftest.py: crate set resolution, ...)"
python3 tools/bindgen_selftest.py || bad "tools/bindgen_selftest.py failed"

echo "== coverage ledger (tools/coverage.py)"
python3 tools/coverage.py --selftest || bad "tools/coverage.py --selftest failed"
# The real report/d.luau only exist after a build against a bind/azalea-src checkout: GEN_REPORT=<OUT_DIR>/GEN_REPORT.json and types/bindings.d.luau.
if [ -f "${GEN_REPORT:-/nonexistent}" ] && [ -f types/bindings.d.luau ]; then
    python3 tools/coverage.py || bad "coverage ledger: unclassified or stale rows (see above; fix tools/coverage.toml)"
else
    echo "coverage ledger vs the real bindings SKIPPED, log A: no GEN_REPORT / types/bindings.d.luau (needs a build with bind/azalea-src)"
fi

echo "== API surface"
# `function name` members, plus function-typed properties (`name: (..) -> ..`: the `goal` / `azalea` library tables are called with `.`, so they have no `self`)
if [ -f types/bindings.d.luau ]; then
    { grep -o '^ *function [A-Za-z_0-9]*' types/bindings.d.luau | awk '{print $2}'; grep -oE '^ +[A-Za-z_0-9]+: \(' types/bindings.d.luau | tr -d ' :('; } | sort -u > /tmp/zenpel_api.txt
    missing=$(comm -23 tools/baseline_api.txt /tmp/zenpel_api.txt)
    [ -z "$missing" ] || bad "names vanished from types/bindings.d.luau: $missing"
else
    echo "API surface SKIPPED, log A: no types/bindings.d.luau (generated by build.rs from bind/azalea-src, not committed)"
fi

echo "== harness glue is a copy of the real glue"
for f in mod.rs convert.rs demo_binds.rs; do   # (generated.rs differs on purpose: OUT_DIR includes vs the harness gen files)
    cmp -s "rust_binds/luau/$f" "harness/src/luau/$f" || bad "harness/src/luau/$f differs from rust_binds/luau/$f"
done
for f in rust_binds/luau/extra_*.rs; do
    [ -e "$f" ] || continue
    cmp -s "$f" "harness/src/luau/$(basename "$f")" || bad "harness/src/luau/$(basename "$f") differs from $f"
done

[ -f rust_binds/luau/generated.rs ] && [ -f harness/src/luau/generated.rs ] || bad "rust_binds/luau/generated.rs and harness/src/luau/generated.rs must both exist"
for m in $(sed -n 's/^mod \(real_[a-z0-9_]*\);.*/\1/p' rust_binds/luau/mod.rs); do
    [ -e "rust_binds/luau/$m.rs" ] || bad "rust_binds/luau/mod.rs declares $m but rust_binds/luau/$m.rs is missing"
done
grep -q 'cfg(feature = "real")' rust_binds/luau/mod.rs && ! grep -q '^real = ' Cargo.toml && bad "mod.rs gates on feature real but Cargo.toml has no such feature"
grep -q 'cfg(feature = "lune")' rust_binds/luau/mod.rs && ! grep -q '^lune = ' Cargo.toml && bad "mod.rs gates on feature lune but Cargo.toml has no such feature"
grep -q '^mod lune_libs;' rust_binds/luau/mod.rs && [ ! -e rust_binds/luau/lune_libs.rs ] && bad "rust_binds/luau/mod.rs declares lune_libs but rust_binds/luau/lune_libs.rs is missing"
for m in $(sed -n 's/^mod \(lune_[a-z0-9_]*\);.*/\1/p' rust_binds/luau/mod.rs); do
    [ -e "rust_binds/luau/$m.rs" ] || bad "rust_binds/luau/mod.rs declares $m but rust_binds/luau/$m.rs is missing"
done
grep -nE 'mlua-luau-scheduler|lune-std-(net|task|process|stdio)' Cargo.toml && bad "Cargo.toml depends on mlua-luau-scheduler or lune-std-net/task/process/stdio (in-tree lune_*.rs replace them)"
grep -E '^mlua = ' Cargo.toml | grep -q '"send"' || bad "the mlua line in Cargo.toml lost the \`send\` feature"
ls harness/src/luau/lune_*.rs >/dev/null 2>&1 && bad "harness/src/luau has lune_*.rs: the harness has no Lune dependency"
ls harness/src/luau/real_*.rs >/dev/null 2>&1 && bad "harness/src/luau has real_*.rs: real-only glue must not be copied into the harness"

if [ "${SKIP_HARNESS:-0}" = 1 ] || ! command -v cargo >/dev/null 2>&1; then
    echo "== harness SKIPPED, log A: SKIP_HARNESS=1 or no cargo on PATH (harness build/run NOT verified)"
else
    echo "== harness build"
    (cd harness && cargo build 2>&1) > /tmp/zenpel_build.log
    status=$?
    grep -E '^error' /tmp/zenpel_build.log && bad "harness build has errors"
    [ "$status" -eq 0 ] || bad "cargo build exited $status"
    echo "== harness run"
    (cd harness && cargo run -q 2>&1) > /tmp/zenpel_run.log
    status=$?
    cat /tmp/zenpel_run.log
    grep -F '[luau]' /tmp/zenpel_run.log && bad "test.luau printed a [luau] error line"
    [ "$status" -eq 0 ] || bad "harness run exited $status"
fi

echo "== bind e2e (tools/bind_e2e.sh: generated register() on real mlua in a scratch harness)"
sh tools/bind_e2e.sh || bad "tools/bind_e2e.sh failed"

if [ "$fail" -eq 0 ]; then echo "check: OK"; else echo "check: FAILED"; fi
exit "$fail"
